import json,math,re
from pathlib import Path
out=Path('outputs/domestic-test/apartments/garden')
# Pixel coordinates traced from the saved Kakao map/aerial, not a cadastral survey.
scaleX=111320*math.cos(math.radians(37.618))/89500;scaleZ=111133/111900
origin=[127.0064181+(640-503)/89500,37.6199851-(360-137)/111900]
def local(p):return [round((p[0]-640)*scaleX,3),round((p[1]-360)*scaleZ,3)]
def poly(ps):return [local(p) for p in ps]
source=json.load(open('work/apartment-garden/merged-buildings.json'))
features=[]
for f in source['features']:
 m=re.fullmatch(r'(\d+)동',f['properties'].get('buld_nm_dc',''))
 if m and 101<=int(m[1])<=128:
  f['properties']['apartment_era']='middle';f['properties']['useAprDay']='20051228';features.append(f)
json.dump({'type':'FeatureCollection','features':features},open(out/'buildings.geojson','w'),ensure_ascii=False,indent=2)
